  }
  function filters() {
    return [...category.filters.map((f) => ({ ...f, options: f.options.map((o) => ({ ...o, label: f.id === "region" ? regionLabel(o.value) : o.label })) })), { id: "aggressiveness", label: "Agressividade", options: [...new Set(maps.map((e) => e.raw.fields.aggressiveness))].filter(Boolean).map((v) => ({ value: v, label: v })) }, { id: "monsterLevel", label: "Nível das criaturas", options: [["1-20", "1–20"], ["21-40", "21–40"], ["41-60", "41–60"], ["61-80", "61–80"], ["81-99", "81–99"], ["100-999", "100+"]].filter(([range]) => maps.some((e) => levels(e).some((n) => {
