      if (id === "aggressiveness") return norm(e.raw.fields.aggressiveness) === norm(v);
      if (id === "monsterLevel") {
        const [a, b] = v.split("-").map(Number);
        return levels(e).some((n) => n >= a && n <= b);
      }
      if (id === "connections") return Boolean(e.raw.fields.adjacentMaps?.length) === (v === "yes");
      return e.filters[id]?.split("|").includes(v);
    });
  }
  const searchText = (e) => [e.id, e.title, e.raw.name, e.raw.fields.mapId, e.raw.fields.region, regionLabel(e.filters.region), JSON.stringify(e.raw.fields), monsters(e).map((m) => m.title + " " + m.raw.name).join(" ")].join(" ");
  const sorts = [["asc", "Nome A–Z"], ["desc", "Nome Z–A"], ["level", "Menor nível de criatura"], ["maxLevel", "Maior nível de criatura"], ["monsters", "Mais monstros"], ["connections", "Mais conexões"]];
  function compare(a, b, sort) {
