      const f = fs.find((f2) => "f_" + f2.id === k), text = k === "q" ? "Busca: " + v : (f?.label || k.slice(2)) + ": " + (f?.options.find((o) => o.value === v)?.label || v), next = new URLSearchParams(p);
      next.delete(k);
