    return section("map-exploration", "Planeje a exploração", `<div class="map-exploration"><div class="map-detail-preview">${minimap(e)}<code>${esc(f.mapId)}</code></div><div class="map-exploration-copy"><span class="map-eyebrow">${esc(regionLabel(e.filters.region))}</span><h3>${esc(mapName(e))}</h3><dl class="map-record-stats"><div><dt>Nível das criaturas</dt><dd>${esc(f.levelRange || "Não informado")}</dd></div><div><dt>${db.gameSource ? "Tipo de área" : "Dificuldade"}</dt><dd>${esc(difficultyLabel(e.filters.difficulty))}</dd></div>${f.aggressiveness ? `<div><dt>Agressividade</dt><dd>${esc(f.aggressiveness)}</dd></div>` : ""}</dl><p class="preserve-text">${esc(f.access || "Acesso não informado.")}</p><a class="secondary-button" href="${esc(href({ region: e.filters.region }))}">Ver mapas de ${esc(regionLabel(e.filters.region))} →</a><p class="map-context-note">${db.gameSource ? "Consulte o nível que libera o mapa nas informações principais." : "A faixa de nível se refere às criaturas, não ao nível exigido para entrar."}</p></div></div>`) + section("map-paths", "Continue a jornada", connections.length ? `<div class="map-path-grid">${connections.map((r) => {
