    if (kind === "weight-calculator") return section("weight", "Peso e Capacidade", `<p>Os pesos abaixo vêm da referência. Informe a capacidade final exibida na ficha do personagem.</p><div class="tool-fields"><label class="field"><span>Capacidade total</span><input id="weightCap" type="number" min="1" value="2000"></label><label class="field"><span>Item</span><select id="refWeightItem">${db.entities.filter((e) => e.type === "items").map((e) => `<option value="${e.id}">${esc(e.title)}</option>`).join("")}</select></label><label class="field"><span>Quantidade</span><input id="refWeightQuantity" type="number" min="1" value="1"></label><button id="weightAdd" class="primary-button">Adicionar</button></div><div id="refWeightRows"></div><output id="refWeightOutput" class="tool-output" aria-live="polite"></output>`);
    if (kind === "damage-calculator") return section("damage-status", "Configuração do simulador", `<p class="reference-note">A extração contém as configurações, mas não o código que calcula o dano. Os dados completos estão abaixo; não apresentamos estimativas como se fossem resultados do simulador original.</p>${value(v.damage)}`);
    if (kind === "top-zeny") return section("ranking", "Top Zeny", `<div class="ref-grid">${["Maiores fazendeiros", "Maiores gastadores", "Classes", "Histórico"].map((s) => `<article class="roadmap-card"><h3>${s}</h3><p>Sem registros de ranking.</p></article>`).join("")}</div><p>O ranking ao vivo ainda não está disponível na wiki.</p>`);
    return "";
  }
  function bindSpecial(kind) {
    if (kind === "cards-db") {
      const draw = () => {
        const q = norm($("#cardQuery").value), cards = db.views.cards.filter((c) => norm([c.cardName, c.cardDescription, c.localCard, c.cardId].join(" ")).includes(q));
        $("#cardCount").textContent = cards.length + " cartas";
        $("#cardResults").innerHTML = cards.map((c) => `<article class="card-reference"><h3>${entryLink("item-" + c.cardId, c.cardName)}</h3><p class="preserve-text">${esc(c.cardDescription)}</p><p>${esc(c.localCard)}</p><p>Monstro: ${entryLink("mob-" + c.monsterId)}</p></article>`).join("");
      };
      $("#cardQuery").addEventListener("input", draw);
      draw();
    }
    if (kind === "experience-calculator") {
      const draw = () => {
        const e = byId.get($("#experienceClass").value), curve = e.job.progressionTables.find((t) => t.id === $("#experienceKind").value);
        const from = Number($("#experienceFrom").value), to = Number($("#experienceTo").value), rate = Number($("#experienceRate").value);
        let total = 0;
        const rows = curve.rows;
        const max = Math.max(...rows.map((r) => Number(r[0])));
        if (!Number.isInteger(from) || !Number.isInteger(to) || from < 1 || to <= from || to > max || !Number.isFinite(rate) || rate <= 0) {
          $("#experienceOutput").textContent = "Informe níveis válidos (1–" + max + "), destino maior que o atual e EXP por abate positiva.";
          return;
        }
        for (const r of rows) if (Number(r[0]) >= from && Number(r[0]) < to) total += Number(String(r[1]).replaceAll(",", ""));
        $("#experienceOutput").textContent = number(total) + " EXP · " + number(Math.ceil(total / rate)) + " abates na taxa informada.";
        $("#experienceTable").innerHTML = table({ ...curve, title: db.views.progressionLabels[curve.id].ptBR });
      };
      $$("#experience input, #experience select").forEach((el) => el.addEventListener("input", draw));
      draw();
    }
    if (kind === "weight-calculator") {
      const inventory = db.views.weight.presets.filter((p) => byId.has(p.itemId)).map((p) => ({ id: p.itemId, quantity: p.quantity }));
      const draw = () => {
        let total = 0;
        $("#refWeightRows").innerHTML = inventory.map((r, i) => {
          const e = byId.get(r.id), weight = Number(String(e.raw.fields.weight || 0).replace(/[^0-9.]/g, "")) * r.quantity;
          total += weight;
          return `<div class="weight-row">${entryLink(e.id)}<span>× ${r.quantity}</span><b>${number(weight)}</b><button data-weight-remove="${i}">Remover</button></div>`;
        }).join("");
        const cap = Number($("#weightCap").value);
        $("#refWeightOutput").textContent = cap > 0 ? number(total) + " / " + number(cap) + " · " + number(total * 100 / cap) + "% da capacidade" : "Informe uma capacidade maior que zero.";
        $$("[data-weight-remove]").forEach((b) => b.addEventListener("click", () => {
          inventory.splice(Number(b.dataset.weightRemove), 1);
          draw();
        }));
      };
      $("#weightAdd").addEventListener("click", () => {
        const n = Number($("#refWeightQuantity").value);
        if (!Number.isSafeInteger(n) || n < 1) {
          $("#refWeightOutput").textContent = "Informe uma quantidade inteira positiva.";
          return;
        }
        inventory.push({ id: $("#refWeightItem").value, quantity: n });
        draw();
      });
      $("#weightCap").addEventListener("input", draw);
      draw();
    }
  }
  function elements() {
    const v = db.views.elements;
    content.innerHTML = `<section class="wiki-window">${title("Tipagem")}<div class="ref-intro">${notice}</div>${section("element-matrix", "Elementos", `<label class="field"><span>Nível do elemento defensor</span><select id="elementLevel">${[1, 2, 3, 4].map((n) => `<option value="${n - 1}">Nível ${n}</option>`).join("")}</select></label><div id="elementTable"></div>`, "Multiplicadores de ataque e defesa elemental por nível.")}${section("races", "Raças", `<div class="ref-grid">${v.races.map((r) => `<article class="roadmap-card"><h3>${esc(r.label)}</h3><p>${esc(r.description)}</p>${filteredLink("monsters", { race: r.filterRace }, "Ver monstros")}</article>`).join("")}</div>`)}${section("sizes", "Tamanho", table({ title: "Arma × tamanho", columns: ["Arma", "Pequeno", "Médio", "Grande"], rows: v.sizes.map((s) => [s.weapon, s.small, s.medium, s.large]) }))}${section("articles", "Páginas de tipagem", `<div class="ref-grid">${db.entities.filter((e) => e.type === "elements").map(tile).join("")}</div>`)}</section>`;
    const draw = () => {
      $("#elementTable").innerHTML = table({ title: "Ataque (linhas) × defesa (colunas) — %", columns: ["ATQ / DEF", ...v.names], rows: v.matrix[Number($("#elementLevel").value)].map((row, i) => [v.names[i], ...row.map((n) => n + "%")]) });
    };
    $("#elementLevel").addEventListener("change", draw);
    draw();
    toc([["element-matrix", "Elementos"], ["races", "Raças"], ["sizes", "Tamanho"], ["articles", "Páginas"]]);
  }
  function route(type, id, query) {
    if (type === "typing" && !cats.has("typing")) type = "elements";
    if (type === "patches" && !cats.has("patches")) type = "events";
    if (db.gameSource && type === "elements") type = "typing";
    if (db.gameSource && type === "events") type = "patches";
    if (!type) {
      home();
      document.title = db.gameSource ? "RO Classic Idle — Wiki Oficial" : "RO Classic Idle — Biblioteca completa";
      return;
    }
    if (id) {
      try {
        id = decodeURIComponent(id);
      } catch {
      }
      const oldIds = { "weight-calculator": "weight-capacity", "experience-calculator": "experience", "rarity-system": "drop-rates" };
      const e = byId.get(id) || byId.get(db.entities.find((e2) => e2.aliases?.includes(id))?.id) || byId.get(db.gameSource ? oldIds[id] : "");
      if (e && (e.type === type || db.gameSource)) {
        detail(e);
        document.title = e.title + " — RO Classic Idle Wiki";
        return;
      }
    } else if (cats.has(type)) {
      document.title = cats.get(type).label + " — RO Classic Idle Wiki";
      if (type === "maps" && !query) return mapCatalog.hub();
      if (type === "items" && !query) return itemCatalog.hub();
      if (type === "classes" && !query) return classes();
      if (type === "elements" && !query && !db.gameSource) return elements();
      if (portal.handles(type) && !query) return portal.hub(type);
      return listing(type, query);
    }
    document.title = "Página não encontrada — RO Classic Idle Wiki";
    content.innerHTML = `<section class="wiki-window">${title("Página não encontrada")}<div class="ref-intro wiki-not-found"><p>${db.gameSource ? "Esta página não existe na wiki do RO Classic Idle. O endereço pode ter mudado depois de uma atualização do jogo." : "Esta entrada não está no acervo de referência."}</p>${db.gameSource ? `<div class="wiki-not-found-actions"><button class="primary-button" type="button" data-search>Buscar na wiki</button><a class="secondary-button" href="#/">Voltar ao início</a></div><nav class="wiki-not-found-links" aria-label="Categorias mais consultadas">${["classes", "items", "monsters", "maps", "quests", "guides"].filter((k) => cats.has(k)).map((k) => `<a href="#/${k}">${esc(cats.get(k).label)}</a>`).join("")}</nav>` : `<a class="secondary-button" href="#/">Voltar ao início</a><p><a href="?fonte=projeto${esc(location.hash)}">Procurar esta entrada nos dados do RO Classic Idle</a></p>`}</div></section>`;
    content.querySelector("[data-search]")?.addEventListener("click", () => showSearch?.());
    toc([]);
  }
  return { route, value, table, classes, detail, listing };
}
